/**
 * @summary Get historical put/call ratio and premium data for a symbol
 */
export const getGetOptionsFlowHistoryUrl = (
  symbol: string,
  params?: GetOptionsFlowHistoryParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/options/${symbol}/history?${stringifiedParams}`
    : `/api/options/${symbol}/history`;
};

export const getOptionsFlowHistory = async (
  symbol: string,
  params?: GetOptionsFlowHistoryParams,
  options?: RequestInit,
): Promise<OptionsFlowSnapshot[]> => {
  return customFetch<OptionsFlowSnapshot[]>(
    getGetOptionsFlowHistoryUrl(symbol, params),
    {
      ...options,
      method: "GET",
    },
  );
};

export const getGetOptionsFlowHistoryQueryKey = (
  symbol: string,
  params?: GetOptionsFlowHistoryParams,
) => {
  return [
    `/api/options/${symbol}/history`,
    ...(params ? [params] : []),
  ] as const;
};

